 const knifeItem=progress.equipped('knife'),knifeSkin=knifeItem&&SKIN_BY_ID[knifeItem.skinId],definition=knifeSkin&&COSMETIC_MODELS[knifeSkin.weapon],signature=knifeSkin?[knifeSkin.id,knifeItem.uid,knifeItem.wear,knifeItem.seed].join(':'):'stock';if(gunViews.knife.finishSignature!==signature){let asset=gunAssets.knife,branch='knife';cosmeticKnifeClips=null;if(definition){asset=await cosmeticAsset(definition.file);const clips=await cosmeticAsset(definition.animations);for(const clip of clips.animations)if(!armsAsset.animations.some(a=>a.name===clip.name))armsAsset.animations.push(clip);cosmeticKnifeClips=definition.clips;branch=definition.clips.idle.split('/').at(-2);}if(generation!==cosmeticBusy)return;const next=bindNativeWeapon(asset,armsModel,branch);configureMaterials(next.root);await applyNativeFinish(next.root,knifeSkin,knifeItem);if(generation!==cosmeticBusy){detachNativeWeapon(next);return;}detachNativeWeapon(gunViews.knife);next.root.visible=player.weapon==='knife';next.finishSignature=signature;gunViews.knife=next;}
 if(!baseBare)baseBare=bareModel;const gloves=progress.equipped('gloves'),skin=gloves&&SKIN_BY_ID[gloves.skinId],def=skin&&COSMETIC_MODELS[skin.weapon];if((activeGloves?.signature||null)!==(skin?[skin.id,gloves.uid,gloves.wear,gloves.seed].join(':'):null)){if(activeGloves){armsModel.remove(activeGloves.root);activeGloves=null;}baseBare.visible=!skin;if(def){const asset=await cosmeticAsset(def.file);if(generation!==cosmeticBusy)return;const root=cloneRig(asset.scene),bones=new Map();armsModel.traverse(o=>{if(o.isBone&&!bones.has(BASE(o.name)))bones.set(BASE(o.name),o);});root.traverse(o=>{if(o.isSkinnedMesh){o.bind(new T.Skeleton(o.skeleton.bones.map(b=>bones.get(BASE(b.name))||b),o.skeleton.boneInverses.map(m=>m.clone())),o.bindMatrix.clone());o.frustumCulled=false;}});configureMaterials(root);armsModel.add(root);await applyNativeFinish(root,skin,gloves);activeGloves={root,signature:[skin.id,gloves.uid,gloves.wear,gloves.seed].join(':')};}else baseBare.visible=true;}
 currentGun=gunViews[player.weapon];if(armsMixer){armsMixer.stopAllAction();viewAnim('idle',true);armsMixer.update(0);updateMount(currentGun);}inventoryUI?.refresh();
