function bloodImpact(bodyHit,direction){ray.set(bodyHit.point.clone().addScaledVector(direction,.03),direction);ray.far=3;const wall=ray.intersectObjects(worldMeshes,false)[0];if(wall)impactDecal(wall,'blood');}

function updateTeamHint(){if(document.querySelector('[data-practice-mode="bomb"].selected'))$('practiceDescription').innerHTML=config.team==='T'?'Plant the bomb at A or B.<br>Eliminate the CTs or protect the planted bomb.':'Defend the A and B bombsites.<br>Eliminate the Ts or hold Use to defuse.';}

function installUpdate4UI(){const news=document.querySelector('.home-news-body');if(news){news.querySelector('.eyebrow').textContent='BROWSER PRACTICE · UPDATE 4';news.querySelector('h1').innerHTML='PLAY THE<br>ANGLE.';news.querySelector('p').innerHTML='Smarter squads. Native bot actions.<br>Improved hits, spectating and weapon framing.';}document.querySelector('.home-news-bottom span').textContent='BOT TACTICS · COMBAT · SPECTATING';$('newsPane').insertAdjacentHTML('afterbegin','<article class="patch-notes"><span class="eyebrow">UPDATE 4 · FIELD WORK</span><h1>PLAY THE ANGLE.</h1><h2>SQUADS THAT MOVE</h2><p>Corrected partial navigation portals, collision movement, jump recovery, native freeze poses and reload recovery. Different guns, reaction times, aim spread, bursts, cover movement, site roles and utility decisions distinguish the four difficulties. Hard and Expert validate throwing arcs and can fire through thin paired surfaces at recently seen positions.</p><h2>FEEL THE FIGHT</h2><p>Refreshed animated hit bounds, optional hit confirmation, armored impact and fall shake, and a closer hand/weapon frame. Native crouch, throw, reload, plant, defuse and death clips replace bind-pose failures.</p><h2>STAY IN THE ROUND</h2><p>First-person spectating after death: Space, arrow keys or mouse buttons switch players. Freeze-time music plays before the round. Leaving the tab releases movement input while the match continues; Escape pauses explicitly.</p><p class="local-inventory-note">Unofficial browser simulation using native assets. Bot tactics, throwing solutions and material penetration approximate Source behavior. The menu uses native Counter-Strike interface assets.</p></article>');}

function installUpdate5News(){const news=document.querySelector('.home-news-body');news.querySelector('.eyebrow').textContent='BROWSER PRACTICE · UPDATE 6';news.querySelector('h1').innerHTML='READY.<br>SET. EQUIP.';news.querySelector('p').innerHTML='Reliable weapons. Native team gloves.<br>Party voice before the first round.';document.querySelector('.home-news-bottom span').textContent='WEAPON FIXES · PARTY VOICE · 3D UNBOXING';news.querySelector('button').onclick=()=>window.CSMenu.select('online');news.querySelector('button').innerHTML='PLAY WITH FRIENDS <span>→</span>';$('newsPane').insertAdjacentHTML('afterbegin','<article class="patch-notes"><span class="eyebrow">UPDATE 5 · BRING YOUR SQUAD</span><h1>PLAY TOGETHER.</h1><h2>ACCOUNTS & FRIENDS</h2><p>Google or email sign-in, editable profiles, friend codes, accepted friend requests, online presence and invitations. Your email and password are handled by Firebase and never displayed to other players.</p><h2>PARTIES & ROOMS</h2><p>Invite up to four friends into a party and queue on the same team. Create an eight-character private room or find a public room in your selected region. Ready up, then let the host start. Empty slots can be filled with bots for 5v5 play.</p><h2>VOICE & TEXT</h2><p>Enable your microphone in Multiplayer or the match menu, then hold K to talk. Choose Team, Party or All voice. Per-player mute and receive-volume controls are available. Y opens All text chat; U opens Team text chat. Voice and text follow their selected audience.</p><h2>LIVE COMBAT</h2><p>The browser host simulates movement, purchases, ammunition, hit traces, grenades and bomb rounds. Guests predict their movement and receive health, scores, opponents and round updates. Dead players can spectate. A bot replaces a disconnected guest.</p><h2>WEAPON VIEWS</h2><p>Explicit held-model visibility, immediate native pose updates and hidden-until-ready skin swaps improve equip reliability. Repair Weapon View in Settings rebuilds the original hand and weapon rigs and restores the standard view offsets while retaining your inventory.</p><p class="local-inventory-note">Casual browser-hosted multiplayer. A modified host can cheat; there is no trusted ranked ladder. Regional matchmaking uses your chosen broad region. CSCoins and cosmetics stay in this browser. Metered relay service uses the existing shared free-plan allowance and may stop if that allowance is exhausted.</p></article>');}
installUpdate5News();
$('newsPane').insertAdjacentHTML('afterbegin','<article class="patch-notes"><span class="eyebrow">UPDATE 6 · READY. SET. EQUIP.</span><h1>BACK IN YOUR HANDS.</h1><h2>WEAPON VISIBILITY</h2><p>Fixed animated guns and grenades disappearing after draw and purchase. Weapon helper bones now belong to their own rig, so changing finishes cannot detach parts from another weapon. Held models finish loading before the match can start. Dual Berettas use the compatible original legacy mesh with native hand animations.</p><h2>TEAM HANDS</h2><p>Stock CT equipment uses native SAS gloves and blue sleeves. Terrorists retain native fingerless gloves and bare arms. Equipped glove finishes override either team.</p><h2>PARTY VOICE IN THE LOBBY</h2><p>Enable the microphone before joining a room. Party members can hold K to talk and use Party text chat before queueing. The same microphone stays ready through the match transition. Disabling it stops capture.</p><h2>CONTAINER OPENING</h2><p>A circular magnified reel, synchronized outer cards, six-second native easing and original opening sounds lead into a rotatable 3D reward preview. Drag to inspect the model; scroll to zoom. Wear and pattern metadata stay attached to the awarded item.</p><h2>DEVELOPER INVENTORY</h2><p>The designated verified tester receives the full native finish catalog, wear samples, testing cases and CSCoins. This local test inventory has no Steam or cash value. Developer items disappear from the active inventory on sign-out.</p></article>');

